  collection_required: '(collection required)',
  changed_summary: '{count} files ({breakdown})',
  summary_what: 'Fill actual value during review (1-line purpose of change)',
  summary_verify: 'Fill actual value during review (1-line verification commands run + results)',
  summary_risk: 'Fill actual value during review (1-line primary risk + rollback method)',
  summary_open_items:
    'Fill actual value during review (P0 <n> / P1 <n> / P2 <n> · highest severity: CRITICAL|HIGH|MEDIUM|LOW|none)',
  summary_ask: 'Please select: {choices}',
  line_budget_exceeded: 'Panel is {lines} lines, over the configured {budget}-line budget — condense before presenting.',
  // Completion report (buildPostApprovalCompletionReport)
