/**
 * Section count, derived rather than restated. Guidance strings interpolate this so a future section
 * add/remove cannot leave a stale "N-section" claim behind in a deny message or a rule doc.
 */
export const REVIEW_SECTION_COUNT = DEFAULT_REVIEW_SECTIONS.length;

/** Project-owned panel/report config (seeded by the git-worktree-isolation transplant bundle). */
export const REVIEW_PANEL_CONFIG_RELPATH = join('.claude', 'config', 'pre-ship-review-panel-sections.json');

/**
 * Reads the project's review panel config and resolves every localizable piece of the panel and
 * the completion report. The file is honoured only when it opts in with `"override": true`:
 * every git-worktree-isolation target already holds a copied seed of this file (customizable, so
 * re-transplant never refreshes it), and reading seeds implicitly would freeze stale sections
 * — or a snapshot of today's defaults — into the live panel. Schema of an opted-in file:
 *
 *   {
 *     "override": true,
 *     "locale": "ko",                          // BCP-47-style tag for the configured copy
 *     "sections": [ ... ],                     // renderTemplateFromSections schema (validated)
 *     "labels": { "<DEFAULT_REPORT_LABELS key>": "..." },
 *     "approval_choices": { "approve": "...", "revise": "...", "abort": "..." },
 *     "line_budget": 60                        // positive integer; over-budget panels get a notice
 *   }
 *
 * Fail-open (R-CM-006 Rule 2): a missing, unreadable or malformed file — or a malformed individual
 * key — falls back to the built-in value for that piece, and `warning` says why. A file carrying
 * non-default `sections` without the opt-in yields a one-line hint instead.
 *
 * @param {string|undefined} projectDir Main repository root.
 * @param {{existsFn?: typeof existsSync, readFn?: typeof readFileSync}} [io] Test-injectable.
 */
export function loadReviewPanelConfig(projectDir, io = {}) {
  // Total by construction: callers include ship guards, where any throw used to fail open.
  try {
    const read = readPanelConfigFile(projectDir, io);
    if (!read.cfg) return builtinPanel(read.warning);
    if (read.cfg.override !== true) return builtinPanel(unadoptedSeedHint(read.cfg));
    return resolveAdoptedPanel(read.cfg);
  } catch (e) {
    return builtinPanel(
      `${REVIEW_PANEL_CONFIG_RELPATH} could not be evaluated (${String(e?.message ?? e).slice(0, 120)}) — built-in panel used`,
    );
  }
}

function builtinPanel(warning) {
  return {
    source: 'default',
    locale: null,
    sections: DEFAULT_REVIEW_SECTIONS,
    labels: resolveReportLabels(null),
    approvalChoices: [...APPROVAL_CHOICES],
    lineBudget: null,
    warning,
  };
}

function unadoptedSeedHint(cfg) {
  if (cfg.sections === undefined) return null;
  if (JSON.stringify(cfg.sections) === JSON.stringify(DEFAULT_REVIEW_SECTIONS)) return null;
  return `${REVIEW_PANEL_CONFIG_RELPATH} has custom sections but no "override": true — ignored, built-in panel used (set "override": true to adopt it)`;
}

const LOCALE_TAG = /^[a-z]{2,3}(-[a-z0-9]{2,8})*$/i;

function resolveAdoptedPanel(cfg) {
  const warnings = [];
  const sectionsError = cfg.sections === undefined ? null : validateSections(cfg.sections);
  if (sectionsError) warnings.push(`\`sections\` rejected (${sectionsError}) — built-in sections used`);
  const budgetOk = Number.isInteger(cfg.line_budget) && cfg.line_budget > 0;
  if (cfg.line_budget !== undefined && !budgetOk) warnings.push('`line_budget` must be a positive integer — ignored');
  const localeOk = typeof cfg.locale === 'string' && LOCALE_TAG.test(cfg.locale.trim());
  if (cfg.locale !== undefined && !localeOk) warnings.push(`\`locale\` ${JSON.stringify(cfg.locale)} is not a locale tag — ignored`);
  return {
    source: 'project',
    locale: localeOk ? cfg.locale.trim() : null,
    sections: cfg.sections === undefined || sectionsError ? DEFAULT_REVIEW_SECTIONS : cfg.sections,
    labels: resolveReportLabels(cfg.labels, warnings),
    approvalChoices: resolveApprovalChoices(cfg.approval_choices, warnings),
    lineBudget: budgetOk ? cfg.line_budget : null,
    warning: warnings.length ? `${REVIEW_PANEL_CONFIG_RELPATH}: ${warnings.join('; ')}` : null,
  };
}

/** `{ cfg }` for a readable JSON object, else `{ cfg: null, warning }` (warning null when simply absent). */
function readPanelConfigFile(projectDir, { existsFn = existsSync, readFn = readFileSync } = {}) {
  if (typeof projectDir !== 'string' || !projectDir) return { cfg: null, warning: null };
  const path = join(projectDir, REVIEW_PANEL_CONFIG_RELPATH);
  try {
    if (!existsFn(path)) return { cfg: null, warning: null };
    const cfg = JSON.parse(String(readFn(path, 'utf-8')));
    if (isPlainObject(cfg)) return { cfg };
    return { cfg: null, warning: `${REVIEW_PANEL_CONFIG_RELPATH} is not an object — using built-in panel` };
  } catch (e) {
    return { cfg: null, warning: `${REVIEW_PANEL_CONFIG_RELPATH} unreadable (${e?.message ?? e}) — using built-in panel` };
  }
}

/**
 * Renders the panel with a loaded config and never throws: if the configured copy fails to render,
 * the built-in panel is shown instead. Ship guards call this — a throw there used to reach the
 * guard's fail-open catch and let ship through with no approval marker.
 *
 * @returns {{text: string, notices: string[]}} panel text + config warning / line-budget notice
 */
export function renderReviewPanel(panel, args = {}) {
  let text;
  let renderWarning = null;
  try {
    text = buildPreShipApprovalReview({
      ...args,
      sections: panel.sections,
      labels: panel.labels,
      approvalChoices: panel.approvalChoices,
    });
  } catch (e) {
    text = buildPreShipApprovalReview(args);
    renderWarning = `${REVIEW_PANEL_CONFIG_RELPATH}: panel render failed (${e?.message ?? e}) — built-in panel shown`;
  }
  const notices = [panel.warning, renderWarning, formatLineBudgetNotice(text, panel.lineBudget, panel.labels)];
  return { text, notices: notices.filter(Boolean) };
}

/**
 * Notice line when a rendered panel exceeds the configured one-page budget, else null.
 * Advisory only: the panel is still printed whole — truncating review material would hide exactly
 * the part nobody budgeted for.
 */
export function formatLineBudgetNotice(panelText, lineBudget, labels = DEFAULT_REPORT_LABELS) {
  if (!Number.isInteger(lineBudget) || lineBudget <= 0) return null;
  const lines = String(panelText ?? '').split('\n').length;
  return lines > lineBudget ? formatLabel(labels.line_budget_exceeded, { lines, budget: lineBudget }) : null;
}

/** `value` unless it was omitted (undefined) — null and '' pass through like destructuring defaults. */
const orDefault = (value, fallback) => (value === undefined ? fallback : value);

/**
 * @param {object} params
 * @param {Array<object>} [params.sections] — Uses `DEFAULT_REVIEW_SECTIONS` when unspecified
 *   (preserves signature/return value).
 * @param {object} [params.labels] — resolved labels (see `loadReviewPanelConfig`); built-in English when omitted.
 * @param {string[]} [params.approvalChoices] — labels in APPROVAL_SPECS order; built-in when omitted.
 *
 * Every context key is passed to the renderer even when the default sections do not print it
 * (`changedSummary`, `severityScale`, `approvalChoices`), so a configured `sections` array can use them.
 */
export function buildPreShipApprovalReview({
  worktreePath,
  branch,
  baseBranch = 'main',
  planPath,
  planChecklist,
  worktreeStatus = 'clean',
  qualityGate,
  testVerify,
  draftPr,
  gitLog = '',
  commitCount = null,
  commitRange = null,
  latestCommit = null,
  prUrl,
  prStatus,
  mergeStatus,
  ciStatus,
  changedFilesTree,
  changedRows = [],
  verificationRows = [],
  summaryWhat,
  summaryVerify,
  summaryRisk,
  summaryOpenItems,
  summaryAsk,
  sections = DEFAULT_REVIEW_SECTIONS,
  labels = DEFAULT_REPORT_LABELS,
  approvalChoices = APPROVAL_CHOICES,
} = {}) {
  const L = labels;
  const choices = APPROVAL_SPECS.map((spec, i) => approvalChoices?.[i] ?? spec.label);
  const choiceList = choices.join(' / ');
  return renderTemplateFromSections(sections, {
    worktreePath,
    summaryWhat: orDefault(summaryWhat, L.summary_what),
    summaryVerify: orDefault(summaryVerify, L.summary_verify),
    summaryRisk: orDefault(summaryRisk, L.summary_risk),
    summaryOpenItems: orDefault(summaryOpenItems, L.summary_open_items),
    summaryAsk: orDefault(summaryAsk, formatLabel(L.summary_ask, { choices: choiceList })),
    branch,
    baseBranch,
    planPath,
    planChecklist: orDefault(planChecklist, L.plan_complete),
    worktreeStatus,
    qualityGate: orDefault(qualityGate, L.fill_result),
    testVerify: orDefault(testVerify, L.fill_result),
    draftPr: orDefault(draftPr, L.not_created),
    gitLog,
    commitCount,
    commitRange,
    latestCommit,
    prUrl: orDefault(prUrl, L.not_created),
    prStatus: orDefault(prStatus, L.pr_status_default),
    mergeStatus: orDefault(mergeStatus, L.before_approval),
    ciStatus: orDefault(ciStatus, L.before_approval),
    changedFilesTree: orDefault(changedFilesTree, L.collection_required),
    changedRows,
    changedSummary: summarizeChangedRows(changedRows, L),
    verificationRows,
    // Enum and choices are interpolated, never restated, so a configured panel cannot drift from the
    // parser (approval-vocabulary.mjs) or the debt ledger (followup-debt.schema.json#severity).
    severityScale: SEVERITY_SCALE.join('|'),
    approvalChoices: choiceList,
    approveChoice: choices[0],
    reviseChoice: choices[1],
    abortChoice: choices[2],
  });
}

/**
 * Post-merge remaining actions, priority-derived from *conditions the report already knows* rather
 * than left as blanks for the AI to fill. The panel asks a human to assign priority because only a
 * human knows what a leftover task costs; here the conditions are closed-form, so guessing is
 * unnecessary and a blank would only invite fabrication.
 *
 *   P0 — the ship did not achieve its purpose (code is not on the trunk). Everything else waits.
 *   P1 — landed correctly, but local state needs a human before the next task starts cleanly.
 *
 * Nothing here is P2: the completion report only ever knows about failures of *this* ship, and a
 * failed ship step is never backlog material.
 *
 * @returns {string[]} Rendered lines (never empty — emits an explicit "None" line instead).
 */
export function renderPrioritizedActions(
  result = {},
  cleanupResult = {},
  postMergeMainStatus = null,
  labels = DEFAULT_REPORT_LABELS,
) {
  const L = labels;
  const actions = [];
  if (result.pending) {
    actions.push({ priority: 'P0', text: L.action_pr_pending });
  }
  if (cleanupResult.ok === false) {
    actions.push({
      priority: 'P1',
      text: formatLabel(L.action_cleanup_incomplete, { hint: valueOrDash(cleanupResult.hint) }),
    });
  }
  if (postMergeMainStatus?.status === 'dirty') {
    actions.push({
      priority: 'P1',
      text: formatLabel(L.action_main_dirty, {
        paths: postMergeMainStatus.dirty_paths?.join(', ') || L.paths_unknown,
      }),
    });
  }
  if (actions.length === 0) return [L.actions_none];
  return actions.map((a) => `- ${a.priority}: ${a.text}`);
}

/**
 * Post-merge issue notes carrying a severity from the same enum as the panel and
 * `followup-debt.schema.json#severity`.
 *
 * Honesty constraint: `result.warnings` is populated from at least five unrelated sites in
 * `ops.mjs` (fetch failure, freshness comparison, superset detection, followup-debt registration,
 * deferred merge). Matching message text to guess a severity would be a fragile fiction, so every
 * warning is emitted at a declared **default floor** of MEDIUM with an explicit instruction to
 * escalate — a stated default is honest in a way an invented per-item verdict is not.
 *
 * @returns {string[]} Rendered lines.
 */
export function renderIssueNotes(result = {}, cleanupResult = {}, labels = DEFAULT_REPORT_LABELS) {
  const L = labels;
  const warnings = Array.isArray(result.warnings) ? result.warnings.filter(Boolean) : [];
  const lines = [formatLabel(L.notes_severity_scale, { scale: SEVERITY_SCALE.join(' | ') })];
  if (warnings.length === 0) {
    lines.push(L.notes_issues_none);
  } else {
    lines.push(L.notes_issues_header);
    for (const w of warnings) lines.push(`  - MEDIUM: ${w}`);
  }
  lines.push(formatLabel(L.notes_workaround, { hint: cleanupResult.hint || L.none }));
  lines.push(L.notes_improvements);
  return lines;
}

export function buildPostApprovalCompletionReport({
  result = {},
  cleanup = true,
  cleanedUp = false,
  cleanupResult = null,
  wtPath = null,
  postMergeMainStatus = null,
  labels = DEFAULT_REPORT_LABELS,
} = {}) {
  const L = labels;
  const cr = cleanupResult ?? {};
  const mergedSituation = result.merged ? L.merged : result.pending ? L.pending : L.not_merged;
  const cleanupSituation = cleanup
    ? cleanedUp
      ? L.cleanup_completed
      : cr.ok === false
        ? L.cleanup_partial
        : L.cleanup_unknown
    : L.cleanup_skipped;
  const branchCleanup = result.merged ? L.branch_cleanup_merged : L.not_performed;
  const mainStatus = cr.sync_status || (cleanup ? L.not_reported : L.not_run);
  const changedTree = result.changed_files_tree || buildFileTree(result.changed_files || [], L);

  return [
    L.report_title,
    L.report_pr_heading,
    `- ${L.report_pr_url}: ${valueOrDash(result.prUrl)}`,
    `- ${L.report_pr_merged}: ${mergedSituation}`,
    `- ${L.report_merge_commit}: ${valueOrDash(result.sha)}`,
    `- ${L.report_ci_status}: ${result.merged ? L.ci_merged : L.ci_pending}`,
    '',
    L.report_cleanup_heading,
    `- ${L.report_worktree_cleanup}: ${cleanupSituation}${wtPath ? ` (${wtPath})` : ''}`,
    `- ${L.report_branch_cleanup}: ${branchCleanup}`,
    `- ${L.report_remote_cleanup}: ${result.merged ? L.remote_cleanup_merged : L.not_performed}`,
    `- ${L.report_ff_status}: ${mainStatus}`,
    '',
    L.report_files_heading,
    '```text',
    changedTree,
    '```',
    '',
    L.report_actions_heading,
    ...renderPrioritizedActions(result, cr, postMergeMainStatus, L),
    '',
    L.report_notes_heading,
    ...renderIssueNotes(result, cr, L),
  ].join('\n');
}
